DB_NUEVO = '"""\nFUTCROSS | Capa de datos sobre Supabase (PostgREST).\n\nTodas las consultas pasan por aca. Ninguna pantalla arma queries por su cuenta.\n"""\n\nfrom __future__ import annotations\n\nimport os\nfrom datetime import date\n\nimport pandas as pd\nimport streamlit as st\nfrom supabase import Client, create_client\n\nimport logic\n\n\n# ---------------------------------------------------------------------\n# Conexion\n# ---------------------------------------------------------------------\ndef secreto(clave: str, defecto=None):\n    """Busca primero en .streamlit/secrets.toml y luego en variables de entorno.\n\n    En local usamos secrets.toml; Hugging Face Spaces inyecta los secretos\n    como variables de entorno. Asi el mismo codigo sirve en los dos lados.\n    """\n    try:\n        if clave in st.secrets:\n            return st.secrets[clave]\n    except Exception:\n        pass\n    return os.environ.get(clave, defecto)\n\n\n@st.cache_resource(show_spinner=False)\ndef cliente() -> Client:\n    url = secreto("SUPABASE_URL")\n    key = secreto("SUPABASE_KEY")\n    if not url or not key:\n        st.error(\n            "Falta configurar la conexion a Supabase. "\n            "Crea el archivo `.streamlit/secrets.toml` con SUPABASE_URL y SUPABASE_KEY "\n            "(o cargalos en Settings > Secrets si ya desplegaste en la nube)."\n        )\n        st.stop()\n    return create_client(url, key)\n\n\ndef _tabla(nombre: str):\n    return cliente().table(nombre)\n\n\ndef _df(rows) -> pd.DataFrame:\n    return pd.DataFrame(rows or [])\n\n\ndef _iso(valor):\n    """Serializa fechas para PostgREST."""\n    return valor.isoformat() if isinstance(valor, date) else valor\n\n\n# ---------------------------------------------------------------------\n# Planes\n# ---------------------------------------------------------------------\ndef listar_planes(solo_activos: bool = True) -> pd.DataFrame:\n    q = _tabla("planes").select("*").order("sesiones")\n    if solo_activos:\n        q = q.eq("activo", True)\n    return _df(q.execute().data)\n\n\ndef crear_plan(nombre, sesiones, vigencia_dias, precio, descripcion=None):\n    return _tabla("planes").insert({\n        "nombre": nombre.strip().upper(),\n        "sesiones": int(sesiones),\n        "vigencia_dias": int(vigencia_dias),\n        "precio": float(precio),\n        "descripcion": descripcion,\n    }).execute().data\n\n\ndef plan(plan_id: str) -> dict | None:\n    r = _tabla("planes").select("*").eq("id", plan_id).limit(1).execute().data\n    return r[0] if r else None\n\n\ndef paquetes_con_plan(plan_id: str) -> int:\n    """Cuantas ventas usan este plan. Sirve para avisar antes de editarlo."""\n    r = (_tabla("paquetes").select("id", count="exact")\n         .eq("plan_id", plan_id).execute())\n    return r.count or 0\n\n\ndef actualizar_plan(plan_id: str, cambios: dict):\n    return _tabla("planes").update(cambios).eq("id", plan_id).execute().data\n\n\n# ---------------------------------------------------------------------\n# Grupos (sede + horario + genero + dias de entrenamiento)\n# ---------------------------------------------------------------------\ndef listar_grupos(solo_activos: bool = True) -> pd.DataFrame:\n    try:\n        q = _tabla("grupos").select("*").order("sede")\n        if solo_activos:\n            q = q.eq("activo", True)\n        return _df(q.execute().data)\n    except Exception:\n        # Si la migracion 009 todavia no se corrio, no romper la pantalla\n        return pd.DataFrame()\n\n\ndef grupo(grupo_id: str) -> dict | None:\n    r = _tabla("grupos").select("*").eq("id", grupo_id).limit(1).execute().data\n    return r[0] if r else None\n\n\ndef crear_grupo(nombre, sede, genero, hora, dias):\n    return _tabla("grupos").insert({\n        "nombre": nombre.strip().upper(),\n        "sede": sede.strip().upper(),\n        "genero": genero,\n        "hora": hora,\n        "dias": dias,\n        "dias_por_semana": len(dias.split()),\n    }).execute().data\n\n\ndef actualizar_grupo(grupo_id: str, cambios: dict):\n    return _tabla("grupos").update(cambios).eq("id", grupo_id).execute().data\n\n\n# ---------------------------------------------------------------------\n# Alumnos\n# ---------------------------------------------------------------------\ndef crear_alumno(datos: dict):\n    limpio = {k: _iso(v) for k, v in datos.items() if v not in (None, "")}\n    return _tabla("alumnos").insert(limpio).execute().data\n\n\ndef actualizar_alumno(alumno_id: str, cambios: dict):\n    limpio = {k: _iso(v) for k, v in cambios.items()}\n    return _tabla("alumnos").update(limpio).eq("id", alumno_id).execute().data\n\n\ndef alumno(alumno_id: str) -> dict | None:\n    r = _tabla("alumnos").select("*").eq("id", alumno_id).limit(1).execute().data\n    return r[0] if r else None\n\n\ndef panel_alumnos(solo_activos: bool = True) -> pd.DataFrame:\n    """Una fila por alumno con su paquete mas relevante (vista v_alumnos_estado)."""\n    q = _tabla("v_alumnos_estado").select("*").order("apellidos")\n    if solo_activos:\n        q = q.eq("activo", True)\n    return _df(q.execute().data)\n\n\ndef buscar_alumnos(texto: str, limite: int = 25) -> pd.DataFrame:\n    """Busca por nombre, apellido, codigo, DNI o telefono."""\n    texto = (texto or "").strip()\n    if not texto:\n        return panel_alumnos().head(limite)\n    patron = f"%{texto}%"\n    filtro = ",".join([\n        f"nombres.ilike.{patron}",\n        f"apellidos.ilike.{patron}",\n        f"codigo.ilike.{patron}",\n        f"dni.ilike.{patron}",\n        f"telefono.ilike.{patron}",\n    ])\n    rows = _tabla("v_alumnos_estado").select("*").or_(filtro).limit(limite).execute().data\n    return _df(rows)\n\n\ndef identificar(texto: str) -> list[dict]:\n    """Busqueda del kiosco: DNI o codigo exacto primero, luego nombre parcial."""\n    texto = (texto or "").strip()\n    if not texto:\n        return []\n\n    digitos = logic.solo_digitos(texto)\n    if digitos and len(digitos) >= 8:\n        exacto = _tabla("v_alumnos_estado").select("*").or_(\n            f"dni.eq.{digitos},telefono.eq.{digitos}"\n        ).execute().data\n        if exacto:\n            return exacto\n\n    codigo = texto.upper()\n    if codigo.startswith("FC-"):\n        exacto = _tabla("v_alumnos_estado").select("*").eq("codigo", codigo).execute().data\n        if exacto:\n            return exacto\n\n    patron = f"%{texto}%"\n    return _tabla("v_alumnos_estado").select("*").or_(\n        f"nombres.ilike.{patron},apellidos.ilike.{patron},codigo.ilike.{patron}"\n    ).limit(8).execute().data\n\n\n# ---------------------------------------------------------------------\n# Paquetes\n# ---------------------------------------------------------------------\ndef paquetes_de(alumno_id: str) -> pd.DataFrame:\n    rows = (_tabla("v_paquetes").select("*")\n            .eq("alumno_id", alumno_id).order("fecha_inicio", desc=True).execute().data)\n    return _df(rows)\n\n\ndef paquete(paquete_id: str) -> dict | None:\n    r = _tabla("v_paquetes").select("*").eq("id", paquete_id).limit(1).execute().data\n    return r[0] if r else None\n\n\ndef paquete_vigente(alumno_id: str) -> dict | None:\n    """El paquete que manda hoy: ACTIVO o CONGELADO, el que vence primero."""\n    rows = (_tabla("v_paquetes").select("*")\n            .eq("alumno_id", alumno_id)\n            .in_("estado_real", ["ACTIVO", "CONGELADO"])\n            .order("fecha_fin").execute().data)\n    return rows[0] if rows else None\n\n\ndef ultimo_paquete(alumno_id: str) -> dict | None:\n    rows = (_tabla("v_paquetes").select("*")\n            .eq("alumno_id", alumno_id).order("fecha_fin", desc=True).limit(1).execute().data)\n    return rows[0] if rows else None\n\n\ndef listar_paquetes(estados: list[str] | None = None) -> pd.DataFrame:\n    q = _tabla("v_paquetes").select("*").order("fecha_fin", desc=True)\n    if estados:\n        q = q.in_("estado_real", estados)\n    return _df(q.execute().data)\n\n\ndef crear_paquete(alumno_id, plan: dict, fecha_inicio: date, precio: float,\n                  medio_pago: str, pagado: bool = True, observacion: str | None = None,\n                  fecha_pedido: date | None = None, sede: str | None = None,\n                  dias_asiste: str | None = None, vendedor: str | None = None,\n                  tipo: str = "NUEVO", sesiones: int | None = None,\n                  vigencia_dias: int | None = None, grupo_id: str | None = None):\n    """Registra la venta con todos los datos del pedido.\n\n    sesiones y vigencia_dias permiten ajustar el plan para una venta puntual\n    (por ejemplo, regalar dos sesiones) sin tocar el catalogo.\n    """\n    total = int(sesiones or plan["sesiones"])\n    dias = int(vigencia_dias or plan["vigencia_dias"])\n    # El plan termina cuando se acaban las sesiones, contando solo los dias\n    # que entrena ese grupo. Si no hay dias, cae al metodo de dias corridos.\n    fecha_fin = logic.fecha_fin_por_calendario(fecha_inicio, total,\n                                               dias_asiste, dias)\n\n    return _tabla("paquetes").insert({\n        "alumno_id": alumno_id,\n        "plan_id": plan.get("id"),\n        "plan_nombre": plan["nombre"],\n        "sesiones_totales": total,\n        "fecha_pedido": (fecha_pedido or fecha_inicio).isoformat(),\n        "fecha_inicio": fecha_inicio.isoformat(),\n        "fecha_fin": fecha_fin.isoformat(),\n        "precio": float(precio),\n        "medio_pago": medio_pago,\n        "pagado": bool(pagado),\n        "sede": sede,\n        "dias_asiste": dias_asiste,\n        "grupo_id": grupo_id,\n        "vendedor": vendedor,\n        "tipo": tipo,\n        "observacion": observacion,\n    }).execute().data\n\n\ndef actualizar_paquete(paquete_id: str, cambios: dict):\n    limpio = {k: _iso(v) for k, v in cambios.items()}\n    return _tabla("paquetes").update(limpio).eq("id", paquete_id).execute().data\n\n\ndef siguiente_pedido() -> int:\n    """Solo para mostrarlo antes de guardar; el numero real lo pone la base."""\n    r = (_tabla("paquetes").select("nro_pedido")\n         .order("nro_pedido", desc=True).limit(1).execute().data)\n    return (r[0]["nro_pedido"] or 0) + 1 if r else 1\n\n\ndef vendedores() -> list:\n    """Los vendedores que ya se usaron, para no escribirlos de nuevo."""\n    r = _tabla("paquetes").select("vendedor").execute().data or []\n    return sorted({(x.get("vendedor") or "").strip() for x in r if x.get("vendedor")})\n\n\ndef sedes() -> list:\n    r = _tabla("alumnos").select("sede").execute().data or []\n    vistas = {(x.get("sede") or "").strip() for x in r if x.get("sede")}\n    return sorted(vistas | {"SURQUILLO"})\n\n\ndef cancelar_paquete(paquete_id: str, motivo: str):\n    return _tabla("paquetes").update({\n        "estado": "CANCELADO",\n        "observacion": motivo,\n    }).eq("id", paquete_id).execute().data\n\n\n# ---------------------------------------------------------------------\n# Congelamientos\n# ---------------------------------------------------------------------\ndef congelar(paquete_id: str, alumno_id: str, motivo: str, detalle: str, desde: date):\n    """Pausa el paquete. La vigencia se extiende recien al reactivar."""\n    _tabla("congelamientos").insert({\n        "paquete_id": paquete_id,\n        "alumno_id": alumno_id,\n        "motivo": motivo,\n        "detalle": detalle,\n        "fecha_inicio": desde.isoformat(),\n    }).execute()\n    _tabla("paquetes").update({"estado": "CONGELADO"}).eq("id", paquete_id).execute()\n\n\ndef reactivar(congelamiento_id: str, hasta: date) -> int:\n    """Cierra el congelamiento y le devuelve al alumno los dias perdidos."""\n    cong = _tabla("congelamientos").select("*").eq("id", congelamiento_id).limit(1).execute().data\n    if not cong:\n        raise ValueError("No se encontro el congelamiento.")\n    cong = cong[0]\n\n    inicio = logic.a_fecha(cong["fecha_inicio"])\n    dias = logic.dias_congelamiento(inicio, hasta)\n\n    vista = paquete(cong["paquete_id"])\n    pq = _tabla("paquetes").select("*").eq("id", cong["paquete_id"]).limit(1).execute().data[0]\n\n    # La nueva fecha de fin es la de su ultima sesion contando desde el alta.\n    # Sumar dias corridos podria dejarla en un dia que su grupo no entrena.\n    restantes = int(vista["sesiones_restantes"]) if vista else 0\n    dias_grupo = (vista or {}).get("dias_asiste")\n    nueva_fin = None\n    if restantes > 0 and dias_grupo:\n        nueva_fin = logic.fecha_de_sesion(hasta, restantes, dias_grupo)\n    if not nueva_fin:\n        nueva_fin = logic.extender(logic.a_fecha(pq["fecha_fin"]), dias)\n\n    _tabla("paquetes").update({\n        "estado": "ACTIVO",\n        "fecha_fin": nueva_fin.isoformat(),\n        "dias_congelados": int(pq.get("dias_congelados") or 0) + dias,\n    }).eq("id", pq["id"]).execute()\n\n    _tabla("congelamientos").update({\n        "fecha_fin": hasta.isoformat(),\n        "dias_aplicados": dias,\n        "activo": False,\n    }).eq("id", congelamiento_id).execute()\n\n    return dias\n\n\ndef congelamientos(activos: bool | None = True) -> pd.DataFrame:\n    q = _tabla("congelamientos").select("*, alumnos(codigo,nombres,apellidos,telefono)")\n    if activos is not None:\n        q = q.eq("activo", activos)\n    rows = q.order("fecha_inicio", desc=True).execute().data or []\n    for r in rows:\n        a = r.pop("alumnos", None) or {}\n        r["codigo"] = a.get("codigo")\n        r["alumno"] = f"{a.get(\'nombres\',\'\')} {a.get(\'apellidos\',\'\')}".strip()\n        r["telefono"] = a.get("telefono")\n    return _df(rows)\n\n\ndef congelamiento_abierto(paquete_id: str) -> dict | None:\n    r = (_tabla("congelamientos").select("*")\n         .eq("paquete_id", paquete_id).eq("activo", True).limit(1).execute().data)\n    return r[0] if r else None\n\n\n# ---------------------------------------------------------------------\n# Asistencias\n# ---------------------------------------------------------------------\ndef ya_marco_hoy(alumno_id: str, fecha: date | None = None) -> bool:\n    fecha = fecha or logic.hoy()\n    r = (_tabla("asistencias").select("id")\n         .eq("alumno_id", alumno_id).eq("fecha", fecha.isoformat())\n         .eq("anulada", False).limit(1).execute().data)\n    return bool(r)\n\n\ndef marcar_asistencia(alumno_id: str, paquete_id: str, sede: str | None = None,\n                      origen: str = "KIOSCO", fecha: date | None = None):\n    payload = {\n        "alumno_id": alumno_id,\n        "paquete_id": paquete_id,\n        "sede": sede,\n        "origen": origen,\n    }\n    if fecha:\n        payload["fecha"] = fecha.isoformat()\n    return _tabla("asistencias").insert(payload).execute().data\n\n\ndef anular_asistencia(asistencia_id: str, quien: str = "admin"):\n    """Al anular, la sesion vuelve automaticamente al saldo del alumno."""\n    return _tabla("asistencias").update({\n        "anulada": True, "anulada_por": quien,\n    }).eq("id", asistencia_id).execute().data\n\n\ndef asistencias(desde: date, hasta: date, incluir_anuladas: bool = False) -> pd.DataFrame:\n    q = (_tabla("v_asistencias").select("*")\n         .gte("fecha", desde.isoformat()).lte("fecha", hasta.isoformat()))\n    if not incluir_anuladas:\n        q = q.eq("anulada", False)\n    return _df(q.order("fecha", desc=True).order("hora", desc=True).execute().data)\n\n\ndef registrar_bloqueo(alumno_id: str | None, texto: str, motivo: str):\n    """Deja constancia de quien quiso entrenar sin paquete valido."""\n    return _tabla("bloqueos").insert({\n        "alumno_id": alumno_id, "texto": texto, "motivo": motivo,\n    }).execute().data\n\n\ndef bloqueos(desde: date, hasta: date) -> pd.DataFrame:\n    rows = (_tabla("bloqueos").select("*, alumnos(codigo,nombres,apellidos,telefono)")\n            .gte("fecha", desde.isoformat()).lte("fecha", hasta.isoformat())\n            .order("fecha", desc=True).order("hora", desc=True).execute().data) or []\n    for r in rows:\n        a = r.pop("alumnos", None) or {}\n        r["codigo"] = a.get("codigo")\n        r["alumno"] = f"{a.get(\'nombres\',\'\')} {a.get(\'apellidos\',\'\')}".strip() or r.get("texto")\n        r["telefono"] = a.get("telefono")\n    return _df(rows)\n'


LOGICA_NUEVA = '"""\nFUTCROSS | Reglas de negocio puras.\n\nEste modulo no toca la base de datos ni Streamlit: solo fechas y numeros.\nAsi se puede testear con `python test_logic.py` sin levantar nada.\n"""\n\nfrom __future__ import annotations\n\nimport re\nimport unicodedata\nfrom datetime import date, datetime, timedelta\nfrom zoneinfo import ZoneInfo\n\nLIMA = ZoneInfo("America/Lima")\n\n# Umbrales para avisar de renovacion\nSESIONES_AVISO = 3      # avisar cuando quedan 3 sesiones o menos\nDIAS_AVISO = 7          # avisar cuando quedan 7 dias o menos\n\n\n# ---------------------------------------------------------------------\n# Fechas\n# ---------------------------------------------------------------------\ndef hoy() -> date:\n    """Fecha de hoy en hora de Lima (no del servidor, que suele estar en UTC)."""\n    return datetime.now(LIMA).date()\n\n\ndef ahora_hhmm() -> str:\n    return datetime.now(LIMA).strftime("%H:%M")\n\n\ndef a_fecha(valor) -> date | None:\n    """Convierte lo que devuelve Supabase (str o date) a un date de Python."""\n    if valor is None or valor == "":\n        return None\n    if isinstance(valor, datetime):\n        return valor.date()\n    if isinstance(valor, date):\n        return valor\n    return date.fromisoformat(str(valor)[:10])\n\n\ndef fecha_fin_plan(fecha_inicio: date, vigencia_dias: int) -> date:\n    """Un plan de 30 dias que arranca el 6-ago vence el 5-set (30 dias de uso)."""\n    return fecha_inicio + timedelta(days=vigencia_dias - 1)\n\n\ndef dias_congelamiento(inicio: date, fin: date) -> int:\n    """Dias perdidos por lesion, contando ambos extremos.\n\n    Lesionado del 10 al 15 = 6 dias que se le devuelven al alumno.\n    """\n    if fin < inicio:\n        raise ValueError("La fecha de alta no puede ser anterior a la de la lesion.")\n    return (fin - inicio).days + 1\n\n\ndef extender(fecha_fin: date, dias: int) -> date:\n    return fecha_fin + timedelta(days=dias)\n\n\ndef edad(fecha_nacimiento: date | None, ref: date | None = None) -> int | None:\n    if not fecha_nacimiento:\n        return None\n    ref = ref or hoy()\n    return ref.year - fecha_nacimiento.year - (\n        (ref.month, ref.day) < (fecha_nacimiento.month, fecha_nacimiento.day)\n    )\n\n\n# ---------------------------------------------------------------------\n# Estado del paquete\n# ---------------------------------------------------------------------\ndef estado_real(paquete: dict, ref: date | None = None) -> str:\n    """Misma logica que la vista v_paquetes, replicada en Python.\n\n    Se usa para previsualizar en pantalla antes de guardar.\n    """\n    ref = ref or hoy()\n    if paquete.get("estado") == "CANCELADO":\n        return "CANCELADO"\n    if paquete.get("estado") == "CONGELADO":\n        return "CONGELADO"\n    usadas = int(paquete.get("sesiones_usadas") or 0)\n    totales = int(paquete.get("sesiones_totales") or 0)\n    if usadas >= totales:\n        return "AGOTADO"\n    fin = a_fecha(paquete.get("fecha_fin"))\n    if fin and ref > fin:\n        return "VENCIDO"\n    return "ACTIVO"\n\n\ndef sesiones_restantes(paquete: dict) -> int:\n    return max(0, int(paquete.get("sesiones_totales") or 0) - int(paquete.get("sesiones_usadas") or 0))\n\n\ndef dias_restantes(paquete: dict, ref: date | None = None) -> int | None:\n    fin = a_fecha(paquete.get("fecha_fin"))\n    if not fin:\n        return None\n    return (fin - (ref or hoy())).days\n\n\n# ---------------------------------------------------------------------\n# Puerta: quien puede entrenar\n# ---------------------------------------------------------------------\ndef puede_entrenar(paquete: dict | None, ya_marco_hoy: bool = False,\n                   ref: date | None = None) -> tuple[bool, str, str]:\n    """Decide si el alumno entra a la sesion.\n\n    Devuelve (autorizado, codigo_motivo, mensaje para pantalla).\n    """\n    if paquete is None:\n        return False, "SIN_PAQUETE", "No tiene un paquete registrado. Pasa por caja para inscribirte."\n\n    estado = estado_real(paquete, ref)\n\n    if estado == "CANCELADO":\n        return False, "CANCELADO", "Este paquete fue anulado. Consulta en recepcion."\n    if estado == "CONGELADO":\n        return False, "CONGELADO", "Tu paquete esta congelado. Avisa en recepcion para reactivarlo."\n    if estado == "AGOTADO":\n        total = paquete.get("sesiones_totales")\n        return False, "AGOTADO", f"Ya usaste tus {total} sesiones. Toca renovar el paquete."\n    if estado == "VENCIDO":\n        fin = a_fecha(paquete.get("fecha_fin"))\n        return False, "VENCIDO", f"Tu paquete vencio el {fin.strftime(\'%d/%m/%Y\')}. Toca renovar."\n    if ya_marco_hoy:\n        return False, "YA_MARCO", "Ya registraste tu asistencia de hoy."\n\n    return True, "OK", "Asistencia registrada. A entrenar."\n\n\n# ---------------------------------------------------------------------\n# Renovaciones\n# ---------------------------------------------------------------------\ndef alerta_renovacion(fila: dict, ref: date | None = None) -> tuple[str, str]:\n    """Clasifica a un alumno para el panel de renovaciones.\n\n    Devuelve (nivel, motivo). Nivel: VENCIDO | URGENTE | PROXIMO | OK.\n    """\n    ref = ref or hoy()\n    estado = fila.get("estado_real") or "SIN PAQUETE"\n\n    if estado in ("SIN PAQUETE", "CANCELADO"):\n        return "VENCIDO", "Sin paquete vigente"\n    if estado == "AGOTADO":\n        return "VENCIDO", "Sesiones agotadas"\n    if estado == "VENCIDO":\n        dias = fila.get("dias_restantes")\n        vencido_hace = abs(int(dias)) if dias is not None else None\n        return "VENCIDO", f"Vencio hace {vencido_hace} dias" if vencido_hace else "Paquete vencido"\n    if estado == "CONGELADO":\n        return "OK", "Congelado (no cuenta para renovacion)"\n\n    rest = fila.get("sesiones_restantes")\n    dias = fila.get("dias_restantes")\n    rest = int(rest) if rest is not None else None\n    dias = int(dias) if dias is not None else None\n\n    if rest is not None and rest <= 1:\n        return "URGENTE", f"Le queda {rest} sesion"\n    if dias is not None and dias <= 3:\n        return "URGENTE", f"Vence en {dias} dias"\n    if rest is not None and rest <= SESIONES_AVISO:\n        return "PROXIMO", f"Le quedan {rest} sesiones"\n    if dias is not None and dias <= DIAS_AVISO:\n        return "PROXIMO", f"Vence en {dias} dias"\n    return "OK", "Al dia"\n\n\ndef ritmo_semanal(sesiones_usadas: int, fecha_inicio: date, ref: date | None = None) -> float:\n    """Sesiones por semana que viene haciendo el alumno.\n\n    Sirve para proyectar si va a terminar sus 12 sesiones antes de que venza.\n    """\n    ref = ref or hoy()\n    dias = max(1, (ref - fecha_inicio).days + 1)\n    return round(sesiones_usadas / (dias / 7), 2)\n\n\ndef proyeccion_termino(sesiones_usadas: int, sesiones_totales: int,\n                       fecha_inicio: date, ref: date | None = None) -> date | None:\n    """Fecha estimada en que agotara sus sesiones al ritmo actual."""\n    ref = ref or hoy()\n    faltan = sesiones_totales - sesiones_usadas\n    if faltan <= 0:\n        return ref\n    ritmo = ritmo_semanal(sesiones_usadas, fecha_inicio, ref)\n    if ritmo <= 0:\n        return None\n    return ref + timedelta(days=int(round(faltan / ritmo * 7)))\n\n\n# ---------------------------------------------------------------------\n# Utilitarios\n# ---------------------------------------------------------------------\ndef normalizar(texto: str) -> str:\n    """Quita tildes y pasa a minusculas, para buscar \'Nunez\' y encontrar \'Nunez\'."""\n    if not texto:\n        return ""\n    sin_tildes = unicodedata.normalize("NFKD", texto)\n    sin_tildes = "".join(c for c in sin_tildes if not unicodedata.combining(c))\n    return sin_tildes.lower().strip()\n\n\ndef solo_digitos(texto) -> str:\n    """Tolera None, NaN y numeros: pandas devuelve NaN en las celdas vacias."""\n    if texto is None:\n        return ""\n    if isinstance(texto, float):\n        if texto != texto:          # NaN\n            return ""\n        texto = f"{texto:.0f}"\n    return re.sub(r"\\D", "", str(texto))\n\n\ndef link_whatsapp(telefono: str, mensaje: str) -> str | None:\n    """Arma el link wa.me. Asume Peru (+51) si el numero viene sin codigo."""\n    num = solo_digitos(telefono)\n    if not num:\n        return None\n    if len(num) == 9:\n        num = "51" + num\n    from urllib.parse import quote\n    return f"https://wa.me/{num}?text={quote(mensaje)}"\n\n\ndef mensaje_renovacion(nombre: str, motivo: str, plan: str = "") -> str:\n    saludo = nombre.split()[0].title() if nombre else "crack"\n    base = f"Hola {saludo}! Te escribimos de FUTCROSS. "\n    if "Vencio" in motivo or "vencid" in motivo.lower() or "agotad" in motivo.lower():\n        return base + "Tu paquete ya termino y te extranamos en la cancha. Renuevalo y seguimos entrenando."\n    return base + f"Ojo que {motivo.lower()}. Renueva a tiempo y no pierdes el ritmo. Nos vemos en la cancha."\n\n\n# ---------------------------------------------------------------------\n# Calendario de entrenamiento\n#\n# FutCross no vende "30 dias": vende sesiones que caen en dias fijos.\n# Un plan de 12 sesiones que arranca el lunes 3 de agosto con grupo de\n# lunes, miercoles y viernes termina el viernes 28, no "30 dias despues".\n# Por eso la fecha de fin se calcula recorriendo el calendario real.\n# ---------------------------------------------------------------------\nINDICE_DIA = {"LUN": 0, "MAR": 1, "MIE": 2, "JUE": 3, "VIE": 4, "SAB": 5, "DOM": 6}\nNOMBRE_DIA = {v: k for k, v in INDICE_DIA.items()}\n\n\ndef dias_a_indices(dias) -> list[int]:\n    """Acepta \'LUN MIE VIE\' o [\'LUN\',\'MIE\',\'VIE\'] y devuelve [0, 2, 4]."""\n    if not dias:\n        return []\n    if isinstance(dias, str):\n        dias = dias.replace(",", " ").split()\n    vistos = {INDICE_DIA[d.strip().upper()[:3]]\n              for d in dias if d.strip().upper()[:3] in INDICE_DIA}\n    return sorted(vistos)\n\n\ndef es_dia_de_entrenamiento(fecha: date, dias) -> bool:\n    return fecha.weekday() in dias_a_indices(dias)\n\n\ndef fecha_de_sesion(inicio: date, numero: int, dias) -> date | None:\n    """Fecha en la que cae la sesion numero N.\n\n    Cuenta desde `inicio` inclusive: si el inicio cae en un dia de\n    entrenamiento, ese dia es la sesion 1.\n    """\n    indices = dias_a_indices(dias)\n    if not indices or numero < 1:\n        return None\n\n    fecha = inicio\n    contadas = 0\n    # Tope de seguridad: 5 anios. Ningun plan real llega ni cerca.\n    for _ in range(365 * 5):\n        if fecha.weekday() in indices:\n            contadas += 1\n            if contadas == numero:\n                return fecha\n        fecha += timedelta(days=1)\n    return None\n\n\ndef fecha_fin_por_calendario(inicio: date, sesiones: int, dias,\n                             vigencia_dias: int | None = None) -> date:\n    """Fecha de la ultima sesion del plan.\n\n    Si el grupo no tiene dias definidos, cae en el metodo viejo de contar\n    dias corridos, para que nada quede sin fecha de fin.\n    """\n    fin = fecha_de_sesion(inicio, sesiones, dias)\n    if fin:\n        return fin\n    return fecha_fin_plan(inicio, vigencia_dias or 30)\n\n\ndef proximas_sesiones(inicio: date, cantidad: int, dias) -> list:\n    """Las fechas exactas de las proximas N sesiones. Para mostrar el\n    cronograma al alumno cuando compra."""\n    indices = dias_a_indices(dias)\n    if not indices or cantidad < 1:\n        return []\n\n    fechas, fecha = [], inicio\n    for _ in range(365 * 5):\n        if fecha.weekday() in indices:\n            fechas.append(fecha)\n            if len(fechas) == cantidad:\n                break\n        fecha += timedelta(days=1)\n    return fechas\n\n\ndef sesiones_entre(desde: date, hasta: date, dias) -> int:\n    """Cuantas sesiones caen en un rango. Sirve para calcular cuantas se\n    perdio un alumno mientras estuvo congelado."""\n    indices = dias_a_indices(dias)\n    if not indices or hasta < desde:\n        return 0\n    total, fecha = 0, desde\n    while fecha <= hasta:\n        if fecha.weekday() in indices:\n            total += 1\n        fecha += timedelta(days=1)\n    return total\n\n\ndef frecuencia(dias) -> str:\n    """\'LUN MIE VIE\' -> \'3 veces por semana\'."""\n    n = len(dias_a_indices(dias))\n    if n == 0:\n        return "sin dias definidos"\n    return "1 vez por semana" if n == 1 else f"{n} veces por semana"\n'


MIGRACION_SQL = '-- =====================================================================\n-- FUTCROSS | Migracion 009 - Grupos de entrenamiento y calendario real\n--\n-- Cambia la forma de calcular el vencimiento. Antes el plan duraba\n-- "30 dias corridos". Ahora el plan dura hasta que se acaban las sesiones,\n-- contando solo los dias que ese grupo entrena.\n--\n-- Un premium de 12 sesiones que arranca el lunes 3 de agosto en el grupo\n-- de lunes, miercoles y viernes termina el viernes 28 de agosto.\n--\n-- Ejecutar TODO en Supabase > SQL Editor > New query > Run.\n-- Es idempotente.\n-- =====================================================================\n\n-- ---------------------------------------------------------------------\n-- 1. GRUPOS (sede + horario + genero + dias)\n-- ---------------------------------------------------------------------\ncreate table if not exists grupos (\n    id              uuid primary key default gen_random_uuid(),\n    nombre          text not null unique,\n    sede            text not null,\n    genero          text not null default \'MASCULINO\'\n                    check (genero in (\'MASCULINO\', \'FEMENINO\', \'MIXTO\')),\n    hora            text,\n    dias            text not null,          -- \'LUN MIE VIE\'\n    dias_por_semana int  not null default 3,\n    activo          boolean not null default true,\n    creado_en       timestamptz not null default now()\n);\n\ninsert into grupos (nombre, sede, genero, hora, dias, dias_por_semana) values\n  (\'SURQUILLO 6:45 AM\',  \'SURQUILLO\',  \'MASCULINO\', \'6:45 a.m.\',      \'LUN MIE VIE\', 3),\n  (\'SURCO 9:00 PM\',      \'SURCO\',      \'MASCULINO\', \'9:00 p.m.\',      \'LUN MIE VIE\', 3),\n  (\'MIRAFLORES 8:00 PM\', \'MIRAFLORES\', \'FEMENINO\',  \'8:00 a 9:00 p.m.\', \'MAR JUE\',   2)\non conflict (nombre) do nothing;\n\n-- ---------------------------------------------------------------------\n-- 2. El alumno y cada pedido pertenecen a un grupo\n-- ---------------------------------------------------------------------\nalter table alumnos\n    add column if not exists grupo_id uuid references grupos(id);\n\nalter table paquetes\n    add column if not exists grupo_id uuid references grupos(id);\n\n-- ---------------------------------------------------------------------\n-- 3. Los planes guardan su frecuencia y duracion en meses\n-- ---------------------------------------------------------------------\nalter table planes\n    add column if not exists dias_por_semana int,\n    add column if not exists meses           int,\n    add column if not exists categoria       text;\n\n-- Catalogo real de FutCross.\n-- PREMIUM entrena 3 veces por semana (solo Surco y Surquillo).\n-- BASICO entrena 2 veces por semana (las tres sedes).\n-- Los precios que no conocemos quedan en 0: se completan en la pantalla\n-- Planes. El unico confirmado es el premium de 1 mes a 240.\ninsert into planes (nombre, sesiones, vigencia_dias, precio, descripcion,\n                    dias_por_semana, meses, categoria) values\n  (\'PLAN PREMIUM 1 MES\',   12,  30, 240.00, \'3 veces por semana durante 1 mes\',   3, 1, \'PREMIUM\'),\n  (\'PLAN PREMIUM 3 MESES\', 36,  90,   0.00, \'3 veces por semana durante 3 meses\', 3, 3, \'PREMIUM\'),\n  (\'PLAN PREMIUM 6 MESES\', 72, 180,   0.00, \'3 veces por semana durante 6 meses\', 3, 6, \'PREMIUM\'),\n  (\'PLAN BASICO 1 MES\',     8,  30,   0.00, \'2 veces por semana durante 1 mes\',   2, 1, \'BASICO\'),\n  (\'PLAN BASICO 3 MESES\',  24,  90,   0.00, \'2 veces por semana durante 3 meses\', 2, 3, \'BASICO\'),\n  (\'PLAN BASICO 6 MESES\',  48, 180,   0.00, \'2 veces por semana durante 6 meses\', 2, 6, \'BASICO\')\non conflict (nombre) do nothing;\n\n-- Los planes de prueba que veniamos arrastrando salen del catalogo\nupdate planes set activo = false\nwhere nombre in (\'Plan Mensual 12 sesiones\', \'Plan Mensual 8 sesiones\',\n                 \'Plan Trimestral 36 sesiones\', \'Pack 4 sesiones\', \'Clase suelta\',\n                 \'PLAN BASICO 36 SESIONES 3 MESES PROMO\');\n\n-- ---------------------------------------------------------------------\n-- 4. Vistas con el grupo incluido\n-- ---------------------------------------------------------------------\ndrop view if exists v_alumnos_estado cascade;\ndrop view if exists v_paquetes cascade;\n\ncreate view v_paquetes as\nwith base as (\n    select p.*,\n           coalesce((select count(*) from asistencias s\n                     where s.paquete_id = p.id and not s.anulada), 0)::int as sesiones_usadas\n    from paquetes p\n)\nselect b.id,\n       b.nro_pedido,\n       b.alumno_id,\n       a.codigo,\n       a.nombres,\n       a.apellidos,\n       (a.nombres || \' \' || a.apellidos) as alumno,\n       a.dni,\n       a.telefono,\n       b.grupo_id,\n       coalesce(g.nombre, b.sede, a.sede)      as grupo,\n       coalesce(g.sede, b.sede, a.sede)        as sede,\n       g.genero,\n       g.hora,\n       coalesce(g.dias, b.dias_asiste, a.dias_asiste) as dias_asiste,\n       a.turno,\n       a.horario,\n       b.plan_id,\n       b.plan_nombre,\n       b.sesiones_totales,\n       b.sesiones_usadas,\n       (b.sesiones_totales - b.sesiones_usadas) as sesiones_restantes,\n       b.fecha_pedido,\n       b.fecha_inicio,\n       b.fecha_fin,\n       (b.fecha_fin - hoy_lima())            as dias_restantes,\n       b.dias_congelados,\n       b.precio,\n       b.medio_pago,\n       b.pagado,\n       b.vendedor,\n       b.tipo,\n       b.estado,\n       b.observacion,\n       b.creado_en,\n       case\n         when b.estado = \'CANCELADO\'                  then \'CANCELADO\'\n         when b.estado = \'CONGELADO\'                  then \'CONGELADO\'\n         when b.sesiones_usadas >= b.sesiones_totales then \'AGOTADO\'\n         when hoy_lima() > b.fecha_fin                then \'VENCIDO\'\n         else \'ACTIVO\'\n       end as estado_real\nfrom base b\njoin alumnos a on a.id = b.alumno_id\nleft join grupos g on g.id = b.grupo_id;\n\ncreate view v_alumnos_estado as\nselect a.id            as alumno_id,\n       a.codigo,\n       a.nombres,\n       a.apellidos,\n       (a.nombres || \' \' || a.apellidos) as alumno,\n       a.dni,\n       a.telefono,\n       a.email,\n       a.grupo_id,\n       ga.nombre       as grupo,\n       coalesce(ga.sede, a.sede)        as sede,\n       ga.genero,\n       ga.hora,\n       coalesce(ga.dias, a.dias_asiste) as dias_asiste,\n       a.turno,\n       a.horario,\n       a.fecha_inscripcion,\n       a.activo,\n       vp.id            as paquete_id,\n       vp.nro_pedido,\n       vp.plan_nombre,\n       vp.fecha_pedido,\n       vp.fecha_inicio,\n       vp.fecha_fin,\n       vp.sesiones_totales,\n       vp.sesiones_usadas,\n       vp.sesiones_restantes,\n       vp.dias_restantes,\n       vp.dias_congelados,\n       vp.vendedor,\n       vp.tipo,\n       vp.precio,\n       vp.medio_pago,\n       coalesce(vp.estado_real, \'SIN PAQUETE\') as estado_real\nfrom alumnos a\nleft join grupos ga on ga.id = a.grupo_id\nleft join lateral (\n    select p.* from v_paquetes p\n    where p.alumno_id = a.id\n    order by case p.estado_real\n               when \'ACTIVO\'    then 0\n               when \'CONGELADO\' then 1\n               else 2\n             end,\n             p.fecha_fin desc\n    limit 1\n) vp on true;\n\ncreate or replace view v_asistencias as\nselect s.id, s.fecha, s.hora, s.sede, s.origen, s.anulada,\n       s.alumno_id, s.paquete_id, a.codigo,\n       (a.nombres || \' \' || a.apellidos) as alumno, a.telefono\nfrom asistencias s\njoin alumnos a on a.id = s.alumno_id;\n'


# ---------------------------------------------------------------------
# Utilidades de archivo
# ---------------------------------------------------------------------
def leer(ruta):
    """Devuelve (texto con \\n, salto de linea original)."""
    datos = ruta.read_bytes()
    salto = "\r\n" if b"\r\n" in datos else "\n"
    return datos.decode("utf-8").replace("\r\n", "\n"), salto


def escribir(ruta, texto, salto):
    ruta.write_bytes(texto.replace("\n", salto).encode("utf-8"))


def respaldar(ruta):
    CARPETA_BACKUP.mkdir(parents=True, exist_ok=True)
    destino = CARPETA_BACKUP / ruta.name
    if not destino.exists():
        shutil.copy2(ruta, destino)
    return destino


def error(mensaje):
    print("")
    print("  ERROR: " + mensaje)
    print("")
    sys.exit(1)


# ---------------------------------------------------------------------
def revertir():
    app = Path("app.py")
    tema = Path("db.py")
    origen_app = CARPETA_BACKUP / "app.py"
    origen_tema = CARPETA_BACKUP / "theme.py"

    if not origen_app.exists() or not origen_tema.exists():
        error("No hay respaldos en " + str(CARPETA_BACKUP) + ". Nada que revertir.")

    shutil.copy2(origen_app, app)
    shutil.copy2(origen_tema, tema)
    print("")
    print("  Revertido. app.py y theme.py volvieron a la version anterior.")
    print("")


def aplicar():
    app = Path("app.py")
    tema = Path("db.py")

    if not app.exists() or not tema.exists():
        error(
            "No encuentro app.py y db.py en esta carpeta.\n"
            "         Parate en la carpeta admin-streamlit y vuelve a intentar:\n"
            "         cd admin-streamlit"
        )

    texto_app, salto_app = leer(app)
    _, salto_tema = leer(tema)

    # ---------------------------------------------------------- idempotencia
    if MARCA_APLICADO in texto_app:
        print("")
        print("  El parche " + PARCHE + " ya estaba aplicado. No se toco nada.")
        print("")
        return

    if MARCA_ORIGINAL not in texto_app:
        error("Faltan los parches 001 a 005. Aplicalos primero, en orden.")

    # ------------------------------------------------ verificar antes de tocar
    # Primero comprobamos que TODOS los bloques calcen. Asi nunca queda el
    # archivo a medio parchear.
    faltantes = []
    for indice, (viejo, _) in enumerate(CAMBIOS_APP, start=1):
        apariciones = texto_app.count(viejo)
        if apariciones != 1:
            faltantes.append((indice, apariciones))

    if faltantes:
        print("")
        print("  No se aplico nada. Estos bloques no calzan con tu app.py:")
        for indice, apariciones in faltantes:
            estado = "no aparece" if apariciones == 0 else str(apariciones) + " veces"
            print("    bloque " + str(indice) + ": " + estado)
        error("Tu app.py fue modificado. Usa el ZIP completo.")

    # ------------------------------------------------------------- respaldar
    respaldar(app)
    respaldar(tema)

    # -------------------------------------------------------------- aplicar
    for viejo, nuevo in CAMBIOS_APP:
        texto_app = texto_app.replace(viejo, nuevo, 1)

    escribir(app, texto_app, salto_app)
    escribir(tema, DB_NUEVO, salto_tema)

    # La migracion queda lista para copiar y pegar en Supabase
    escribir(Path("migracion-009.sql"), MIGRACION_SQL, salto_app)
    escribir(Path("logic.py"), LOGICA_NUEVA, salto_app)

    # ---------------------------------------------------------- verificacion
    final_app, _ = leer(app)
    final_tema, _ = leer(tema)
    sql = Path("migracion-009.sql")

    logica = Path("logic.py")
    texto_logica = leer(logica)[0] if logica.exists() else ""
    controles = [
        ("Calendario de entrenamiento", "def fecha_de_sesion" in texto_logica),
        ("Fin del plan por calendario", "fecha_fin_por_calendario" in texto_logica),
        ("Cronograma de sesiones", "def proximas_sesiones" in texto_logica),
        ("Selector de grupo", "def selector_de_grupo" in final_app),
        ("Grupos en la capa de datos", "def listar_grupos" in final_tema),
        ("Reactivar usa el calendario", "fecha_de_sesion(hasta, restantes" in final_tema),
        ("Migracion SQL generada", sql.exists() and sql.stat().st_size > 3000),
        ("Version 1.9", 'VERSION = "1.9"' in final_app),
    ]

    print("")
    print("  Parche " + PARCHE + " aplicado")
    print("  " + "-" * 46)
    for etiqueta, ok in controles:
        print("  [" + ("OK" if ok else "  ") + "]  " + etiqueta)

    if not all(ok for _, ok in controles):
        error("Alguna verificacion fallo. Revisa " + str(CARPETA_BACKUP))

    print("  " + "-" * 46)
    print("  Respaldo en: " + str(CARPETA_BACKUP))
    print("")
    print("  PASO OBLIGATORIO antes de usarlo:")
    print("    1. Abre migracion-009.sql (quedo en esta carpeta)")
    print("    2. Copia todo y pegalo en Supabase > SQL Editor > Run")
    print("    3. Recien ahi reinicia Streamlit")
    print("")


if __name__ == "__main__":
    if "--revertir" in sys.argv:
        revertir()
    else:
        aplicar()